//! Time zones by place name, abbreviation or UTC offset.

use std::sync::{LazyLock, OnceLock};

use jiff::Zoned;
use jiff::tz::{Offset, TimeZone};

use crate::config::ZoneCodeCorrection;
use crate::hash::TableMap;

const PLACES: &str = include_str!("places.txt");
/// Generated by scripts/airports.py; codes in capitals count only in capitals.
const AIRPORTS: &str = include_str!("airports.txt");
/// About 57k city names from GeoNames with their zones and coordinates, sorted for binary search.
const CITIES: &str = include_str!("cities.txt");
/// Where each zone's principal place is, from the tz database.
const ZONE_COORDINATES: &str = include_str!("zone_coordinates.txt");

/// Zone ids whose last segment is not a useful place name.
const HOLIDAY_ZONE_CITIES: &[&str] = &["christmas", "easter"];

const SKIPPED_PREFIXES: &[&str] = &[
    "Etc/",
    "US/",
    "Canada/",
    "Mexico/",
    "Brazil/",
    "Chile/",
    "Antarctica/",
    "America/Indiana/",
    "America/Kentucky/",
    "America/North_Dakota/",
    "posix/",
    "right/",
];

/// A place from `places.txt` or the zone database.
struct Listed {
    /// IANA zone id, or a fixed offset in POSIX form.
    zone: String,
    kind: PlaceKind,
    /// Written in capitals: "PST", "LAX", "UK".
    upper: bool,
    /// A place only in capitals: the airport "MAN", not "man".
    capitals_only: bool,
    /// Latitude and longitude of a listed city, if `cities.txt` doesn't have them.
    coordinates: Option<(f64, f64)>,
    /// The zone, loaded on first use.
    loaded: OnceLock<Option<TimeZone>>,
}

impl Listed {
    fn new(zone: String, coordinates: Option<(f64, f64)>) -> Listed {
        Listed { zone, kind: PlaceKind::City, upper: false, capitals_only: false, coordinates, loaded: OnceLock::new() }
    }

    /// Reads "Europe/London" or "Europe/London 51.38 -2.36".
    fn parse(text: &str, kind: PlaceKind, upper: bool) -> Listed {
        let mut fields = text.split_whitespace();
        let zone = fields.next().unwrap_or_default().to_string();
        let mut number = || fields.next()?.parse::<f64>().ok();
        let coordinates = number().zip(number());
        Listed { kind, upper, ..Listed::new(zone, coordinates) }
    }

    fn time_zone(&self) -> Option<TimeZone> {
        self.loaded.get_or_init(|| listed(&self.zone)).clone()
    }
}

/// Place names outside the abbreviations that are written in capitals.
const ACRONYMS: &[&str] = &["drc", "uae", "uk", "usa", "us", "dc", "nyc"];

/// Lowercase place name -> its zone.
static INDEX: LazyLock<TableMap<String, Listed>> = LazyLock::new(|| {
    let mut index = TableMap::default();
    // Each section of the file holds one kind of place.
    let mut kind = PlaceKind::City;
    for line in PLACES.lines().map(str::trim).filter(|l| !l.is_empty()) {
        if let Some(heading) = line.strip_prefix("# ") {
            kind = match heading.split(['.', ' ']).next().unwrap_or_default() {
                "Abbreviations" => PlaceKind::TimeZone,
                "Countries" => PlaceKind::Country,
                "US" | "Canadian" | "Australian" => PlaceKind::Region,
                "Cities" => PlaceKind::City,
                "Airports" => PlaceKind::Airport,
                _ => kind,
            };
            continue;
        }
        if let Some((name, rest)) = line.split_once('=') {
            let name = name.trim();
            // Abbreviations and airport codes are written in capitals.
            let code = matches!(kind, PlaceKind::TimeZone | PlaceKind::Airport)
                && name.len() <= 5
                && !name.contains(' ')
                && name != "zulu";
            let upper = code || ACRONYMS.contains(&name.to_lowercase().as_str());
            // Written in capitals in the file: a word too, so a place only in capitals.
            let capitals_only = name.chars().any(char::is_uppercase);
            let listed = Listed { capitals_only, ..Listed::parse(rest, kind, upper) };
            index.insert(name.to_lowercase(), listed);
        }
    }
    // Cities from the zone database itself: "Asia/Almaty" -> "almaty". The
    // bundled copy lists the same names as the system one without opening
    // every zone file; `find` checks that the system has the zone.
    for id in jiff::tz::TimeZoneDatabase::bundled().available() {
        let id = id.as_str();
        if !id.contains('/') || SKIPPED_PREFIXES.iter().any(|p| id.starts_with(p)) {
            continue;
        }
        let city = zone_city_name(id);
        // "Christmas" and "Easter" are holidays; the islands are listed by their full names.
        if HOLIDAY_ZONE_CITIES.contains(&city.as_str()) {
            continue;
        }
        index.entry(city).or_insert_with(|| Listed::new(id.to_string(), None));
    }
    // Airports last: places and zone cities win ("IST" is India's time, "Yap" an island).
    for line in AIRPORTS.lines().filter(|l| !l.starts_with('#')) {
        if let Some((code, rest)) = line.split_once(" = ") {
            let capitals_only = code.chars().any(char::is_uppercase);
            let listed = Listed { capitals_only, ..Listed::parse(rest, PlaceKind::Airport, true) };
            index.entry(code.to_lowercase()).or_insert(listed);
        }
    }
    index
});

/// The `name\tzone\tlatitude\tlongitude` lines of `cities.txt`, without the header.
fn city_lines() -> &'static str {
    let mut data = CITIES;
    while data.starts_with('#') {
        data = data.split_once('\n').map_or("", |(_, rest)| rest);
    }
    data
}

/// All cities as their name and the rest of their line.
fn cities() -> impl Iterator<Item = (&'static str, &'static str)> {
    // Scanning bytes is much faster here than `lines()` and `split_once()`.
    let mut rest = city_lines();
    std::iter::from_fn(move || {
        while !rest.is_empty() {
            let end = rest.bytes().position(|b| b == b'\n').unwrap_or(rest.len());
            let line = &rest[..end];
            rest = rest.get(end + 1..).unwrap_or_default();
            if let Some(tab) = line.bytes().position(|b| b == b'\t') {
                return Some((&line[..tab], &line[tab + 1..]));
            }
        }
        None
    })
}

/// Names of listed places and IANA zone cities, sorted.
pub(crate) fn place_names() -> Vec<&'static str> {
    let mut names: Vec<&str> = INDEX.keys().map(String::as_str).collect();
    names.sort_unstable();
    names
}

/// Names of the cities in `cities.txt`, sorted.
#[cfg(test)]
pub(crate) fn city_names() -> impl Iterator<Item = &'static str> {
    cities().map(|(name, _)| name)
}

/// A city: its zone id and where it is.
#[derive(Clone, Copy, Debug, PartialEq)]
struct City {
    zone: &'static str,
    latitude: f64,
    longitude: f64,
}

impl City {
    /// Reads "Asia/Tokyo\t35.69\t139.69".
    fn parse(line_rest: &'static str) -> Option<City> {
        let mut fields = line_rest.split('\t');
        let zone = fields.next()?;
        let latitude = fields.next()?.parse().ok()?;
        let longitude = fields.next()?.parse().ok()?;
        Some(City { zone, latitude, longitude })
    }
}

/// Binary search right in the sorted text: no index to build at startup.
fn city(name: &str) -> Option<City> {
    let data = city_lines();
    let bytes = data.as_bytes();
    // Lines starting before `lo` sort before `name`, lines starting at `hi` or later after it.
    let (mut lo, mut hi) = (0, data.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        // The first line starting at `mid` or later; only its name is read.
        let start = match mid {
            0 => 0,
            _ => match bytes[mid - 1..hi].iter().position(|&b| b == b'\n') {
                Some(p) if mid + p < hi => mid + p,
                _ => {
                    hi = mid;
                    continue;
                }
            },
        };
        let tab = start + bytes[start..].iter().position(|&b| b == b'\t')?;
        match data[start..tab].cmp(name) {
            std::cmp::Ordering::Equal => {
                let end = tab + bytes[tab..].iter().position(|&b| b == b'\n').unwrap_or(data.len() - tab);
                return City::parse(&data[tab + 1..end]);
            }
            std::cmp::Ordering::Less => lo = start + 1,
            std::cmp::Ordering::Greater => hi = start,
        }
    }
    None
}

/// Longest place name in words: "San Fernando del Valle de Catamarca".
pub const MAX_WORDS: usize = 6;

/// Finds a zone by lowercase place name or abbreviation, like "new york" or "pst".
pub fn find(name: &str) -> Option<TimeZone> {
    if let Some(zone) = INDEX.get(name).and_then(Listed::time_zone) {
        return Some(zone);
    }
    // Full ids like "asia/tokyo" typed by the user.
    if name.contains('/') {
        return TimeZone::get(name).ok();
    }
    city(name).and_then(|c| TimeZone::get(c.zone).ok())
}

/// A city of `cities.txt` by lowercase name, past listed places: "waw" when "WAW" is the airport.
pub(crate) fn find_city(name: &str) -> Option<TimeZone> {
    city(name).and_then(|c| TimeZone::get(c.zone).ok())
}

/// A name without its diacritics, if it had any: "curaçao" -> "curacao", "côte d'ivoire" -> "cote d'ivoire".
pub(crate) fn without_diacritics(name: &str) -> Option<String> {
    if name.is_ascii() {
        return None;
    }
    let mut out = String::with_capacity(name.len());
    for c in name.chars() {
        let plain = match c {
            'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' | 'ā' | 'ă' | 'ą' => "a",
            'ç' | 'ć' | 'č' => "c",
            'ď' | 'đ' | 'ð' => "d",
            'è' | 'é' | 'ê' | 'ë' | 'ē' | 'ė' | 'ę' | 'ě' => "e",
            'ğ' => "g",
            'ì' | 'í' | 'î' | 'ï' | 'ī' | 'ı' | 'į' => "i",
            'ł' | 'ľ' => "l",
            'ñ' | 'ń' | 'ň' => "n",
            'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' | 'ō' | 'ő' => "o",
            'ř' => "r",
            'ś' | 'š' | 'ş' | 'ș' => "s",
            'ť' | 'ţ' | 'ț' => "t",
            'ù' | 'ú' | 'û' | 'ü' | 'ū' | 'ů' | 'ű' => "u",
            'ý' | 'ÿ' => "y",
            'ź' | 'ż' | 'ž' => "z",
            'æ' => "ae",
            'œ' => "oe",
            'ß' => "ss",
            'þ' => "th",
            '’' | 'ʻ' => "'",
            c => {
                out.push(c);
                continue;
            }
        };
        out.push_str(plain);
    }
    (out != name).then_some(out)
}

/// What kind of place a name is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PlaceKind {
    City,
    Country,
    /// A state or province: "Texas", "Ontario".
    Region,
    Airport,
    /// A zone abbreviation or offset: "PST", "UTC+5".
    TimeZone,
}

/// A place a line names: its time zone and how to show its name.
#[derive(Clone, Debug)]
pub struct Place {
    /// For captions: "Paris", "PST", "UTC+5:30".
    pub name: String,
    pub zone: TimeZone,
    pub kind: PlaceKind,
}

impl Place {
    /// A place written as `written` in a line: "tokyo" is shown as "Tokyo", "pst" as "PST".
    pub(crate) fn written(written: &str, zone: TimeZone) -> Place {
        let listed = INDEX.get(&written.replace('-', " ").to_lowercase());
        let name = match listed {
            Some(listed) if listed.upper => written.to_uppercase(),
            _ if written.chars().any(char::is_uppercase) => written.to_string(),
            _ => title_case(written),
        };
        Place { name, zone, kind: listed.map_or(PlaceKind::City, |l| l.kind) }
    }

    /// A fixed offset from UTC: "UTC+5:30".
    pub(crate) fn offset(zone: TimeZone) -> Option<Place> {
        let name = offset_label(zone.to_fixed_offset().ok()?);
        Some(Place { name, zone, kind: PlaceKind::TimeZone })
    }

    /// The place a zone stands for: "New York" for America/New_York, "UTC+5" for a fixed offset.
    pub fn of_zone(zone: &TimeZone) -> Place {
        let (name, kind) = match zone.iana_name() {
            Some(id) if id.contains('/') && !id.starts_with("Etc/") => {
                (id.rsplit('/').next().unwrap_or(id).replace('_', " "), PlaceKind::City)
            }
            Some("UTC" | "Etc/UTC" | "Etc/GMT") => ("UTC".to_string(), PlaceKind::TimeZone),
            _ => (offset_label(zone.to_offset(jiff::Timestamp::now())), PlaceKind::TimeZone),
        };
        Place { name, zone: zone.clone(), kind }
    }
}

/// Daylight saving abbreviations and the region whose summer time they name.
const DAYLIGHT_REGIONS: &[(&str, &str)] = &[
    ("edt", "America/New_York"),
    ("cdt", "America/Chicago"),
    ("mdt", "America/Denver"),
    ("pdt", "America/Los_Angeles"),
    ("akdt", "America/Anchorage"),
    ("adt", "America/Halifax"),
    ("ndt", "America/St_Johns"),
    ("bst", "Europe/London"),
    ("west", "Europe/Lisbon"),
    ("cest", "Europe/Paris"),
    ("eest", "Europe/Athens"),
    ("acdt", "Australia/Adelaide"),
    ("aedt", "Australia/Sydney"),
    ("nzdt", "Pacific/Auckland"),
];

/// The name (lowercase) is a zone abbreviation: "pst", "cest".
/// An airport code that is also a word, so it counts only in capitals: "MAN".
pub(crate) fn capitals_only(name: &str) -> bool {
    INDEX.get(name).is_some_and(|l| l.capitals_only)
}

pub(crate) fn is_code(name: &str) -> bool {
    INDEX.get(name).is_some_and(|l| l.kind == PlaceKind::TimeZone && l.upper)
}

/// The zone an abbreviation names, as the config reads abbreviations.
pub(crate) fn corrected(name: &str, zone: TimeZone, correction: ZoneCodeCorrection) -> TimeZone {
    if !is_code(name) {
        return zone;
    }
    match correction {
        ZoneCodeCorrection::OnlyNonSummerCodes => zone,
        // "EDT" in winter is New York's time too.
        ZoneCodeCorrection::Automatic => DAYLIGHT_REGIONS
            .iter()
            .find(|(code, _)| *code == name)
            .and_then(|(_, region)| TimeZone::get(region).ok())
            .unwrap_or(zone),
        // "EST" is UTC-5 all year: the region's standard time, the smaller of its offsets.
        ZoneCodeCorrection::Never if zone.iana_name().is_some() => {
            let offset = |s| jiff::Timestamp::from_second(s).map(|t| zone.to_offset(t).seconds()).unwrap_or(0);
            let standard = offset(1_768_435_200).min(offset(1_784_073_600));
            fixed(standard).unwrap_or(zone)
        }
        ZoneCodeCorrection::Never => zone,
    }
}

/// A place on Earth, for the sun: `sunrise in Tokyo`.
#[derive(Clone, Debug)]
pub struct Location {
    pub zone: TimeZone,
    /// Degrees north.
    pub latitude: f64,
    /// Degrees east.
    pub longitude: f64,
}

/// Where a city or an airport is. Regions have no single place: "Texas" is
/// `None`, but "New York" is the city, which has the state's zone.
pub fn locate(name: &str) -> Option<Location> {
    let zone = find(name)?;
    let listed = INDEX.get(name).and_then(|l| l.coordinates);
    let city = || city(name).filter(|c| same_time(&zone, c.zone)).map(|c| (c.latitude, c.longitude));
    // A zone's own city: "Zurich" for Europe/Zurich.
    let zone_city = || {
        let id = zone.iana_name()?;
        (zone_city_name(id) == name).then(|| zone_coordinates(id))?
    };
    let (latitude, longitude) = listed.or_else(city).or_else(zone_city)?;
    Some(Location { zone, latitude, longitude })
}

/// Where a city of `cities.txt` is, past listed places: "waw" when "WAW" is the airport.
pub(crate) fn locate_city(name: &str) -> Option<Location> {
    let c = city(name)?;
    Some(Location { zone: TimeZone::get(c.zone).ok()?, latitude: c.latitude, longitude: c.longitude })
}

/// Great-circle distance between two places in kilometers, on a sphere of the Earth's mean radius.
pub fn distance_km(a: &Location, b: &Location) -> f64 {
    const EARTH_RADIUS_KM: f64 = 6371.0088;
    let (lat1, lat2) = (a.latitude.to_radians(), b.latitude.to_radians());
    let (dlat, dlon) = (lat2 - lat1, (b.longitude - a.longitude).to_radians());
    let h = (dlat / 2.0).sin().powi(2) + lat1.cos() * lat2.cos() * (dlon / 2.0).sin().powi(2);
    2.0 * EARTH_RADIUS_KM * h.sqrt().min(1.0).asin()
}

/// "America/Port-au-Prince" -> "port au prince", as hyphenated names are read.
fn zone_city_name(id: &str) -> String {
    id.rsplit('/').next().unwrap_or(id).replace(['_', '-'], " ").to_lowercase()
}

/// The principal place of a zone: New York for America/New_York.
pub fn zone_location(zone: &TimeZone) -> Option<Location> {
    let (latitude, longitude) = zone_coordinates(zone.iana_name()?)?;
    Some(Location { zone: zone.clone(), latitude, longitude })
}

fn zone_coordinates(id: &str) -> Option<(f64, f64)> {
    let line = ZONE_COORDINATES.lines().find(|l| l.split('\t').next() == Some(id))?;
    let mut fields = line.split('\t').skip(1).map(|f| f.parse().ok());
    Some((fields.next()??, fields.next()??))
}

/// The zones keep the same time, as a zone and its old name do: Asia/Calcutta and Asia/Kolkata.
fn same_time(zone: &TimeZone, id: &str) -> bool {
    if zone.iana_name() == Some(id) {
        return true;
    }
    let Ok(other) = TimeZone::get(id) else { return false };
    // Mid-month in each season of 2026, to catch daylight saving time.
    [1_768_435_200, 1_776_211_200, 1_784_073_600, 1_792_022_400]
        .into_iter()
        .filter_map(|s| jiff::Timestamp::from_second(s).ok())
        .all(|t| zone.to_offset(t) == other.to_offset(t))
}

/// A zone from `places.txt`: an IANA id or a fixed offset in POSIX form ("EDT4").
fn listed(id: &str) -> Option<TimeZone> {
    TimeZone::get(id).or_else(|_| TimeZone::posix(id)).ok()
}

/// The known place spelled most like `name`, for "did you mean" hints.
pub fn suggest(name: &str) -> Option<String> {
    if name.chars().count() < 4 {
        return None;
    }
    let limit = if name.chars().count() <= 5 { 1 } else { 2 };
    let target: Vec<char> = name.chars().collect();
    let mut row = Vec::new();
    let mut distance =
        |k: &str| (k.len().abs_diff(name.len()) <= limit).then(|| edit_distance(k, &target, limit, &mut row));
    // Listed places win ties over other cities, and ties among them go alphabetically.
    let listed = INDEX.keys().filter_map(|k| Some((distance(k)?, k.as_str()))).min();
    let city = cities().filter_map(|(city, _)| Some((distance(city)?, city))).min_by_key(|&(d, _)| d);
    let (distance, best) = match (listed, city) {
        (Some(listed), Some(city)) if city.0 < listed.0 => city,
        (listed, city) => listed.or(city)?,
    };
    // "west" is a zone only in capitals: "WEST".
    let capitals = INDEX.get(best).is_some_and(|l| l.capitals_only || l.upper);
    (distance <= limit).then(|| if capitals { best.to_uppercase() } else { title_case(best) })
}

/// Levenshtein distance from `a` to `b`, or anything above `limit` once it
/// can't get back under it.
fn edit_distance(a: &str, b: &[char], limit: usize, row: &mut Vec<usize>) -> usize {
    row.clear();
    row.extend(0..=b.len());
    for (i, ca) in a.chars().enumerate() {
        let mut diagonal = row[0];
        row[0] = i + 1;
        for (j, &cb) in b.iter().enumerate() {
            let substitution = diagonal + usize::from(ca != cb);
            diagonal = row[j + 1];
            row[j + 1] = substitution.min(row[j] + 1).min(diagonal + 1);
        }
        if row.iter().all(|&d| d > limit) {
            return limit + 1;
        }
    }
    row[b.len()]
}

/// "new york" -> "New York", "aix-en-provence" -> "Aix-en-Provence".
fn title_case(name: &str) -> String {
    const SMALL: &[&str] =
        &["de", "del", "der", "di", "du", "da", "do", "dos", "en", "la", "le", "of", "on", "sur", "upon"];
    let mut out = String::with_capacity(name.len());
    for (i, word) in name.split_inclusive([' ', '-']).enumerate() {
        let bare = word.trim_end_matches([' ', '-']);
        let mut chars = word.chars();
        match chars.next() {
            Some(c) if i == 0 || !SMALL.contains(&bare) => out.extend(c.to_uppercase().chain(chars)),
            _ => out.push_str(word),
        }
    }
    out
}

/// A zone with a fixed UTC offset in seconds.
pub fn fixed(seconds: i32) -> Option<TimeZone> {
    Offset::from_seconds(seconds).ok().map(Offset::to_time_zone)
}

/// A short label for the zone at that moment: "JST", "CEST" or "UTC+5".
/// Only abbreviations that read back as the same time are used: Belize's
/// "CST" would be Chicago's, which keeps daylight saving time.
pub fn label(time: &Zoned) -> String {
    let abbr = time.strftime("%Z").to_string();
    let same_time = || find(&abbr.to_lowercase()).is_some_and(|zone| zone.to_offset(time.timestamp()) == time.offset());
    if !abbr.starts_with(['+', '-']) && !abbr.is_empty() && same_time() {
        return abbr;
    }
    offset_label(time.offset())
}

/// "UTC", "UTC+5", "UTC-3:30".
pub fn offset_label(offset: Offset) -> String {
    let secs = offset.seconds();
    if secs == 0 {
        return "UTC".into();
    }
    let sign = if secs < 0 { '-' } else { '+' };
    let (h, m) = (secs.abs() / 3600, secs.abs() % 3600 / 60);
    if m == 0 { format!("UTC{sign}{h}") } else { format!("UTC{sign}{h}:{m:02}") }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_places() {
        assert_eq!(find("brazil").unwrap().iana_name(), Some("America/Sao_Paulo"));
        assert_eq!(find("osaka").unwrap().iana_name(), Some("Asia/Tokyo"));
        assert_eq!(find("tokyo").unwrap().iana_name(), Some("Asia/Tokyo"));
        assert_eq!(find("new york").unwrap().iana_name(), Some("America/New_York"));
        assert_eq!(find("buenos aires").unwrap().iana_name(), Some("America/Argentina/Buenos_Aires"));
        assert!(find("qwertyville").is_none());
    }

    #[test]
    fn cities_come_from_geonames() {
        assert_eq!(find("marseille").unwrap().iana_name(), Some("Europe/Paris"));
        assert_eq!(find("sao jose dos campos").unwrap().iana_name(), Some("America/Sao_Paulo"));
        let names: Vec<&str> = cities().map(|(city, _)| city).collect();
        assert!(names.windows(2).all(|w| w[0] < w[1]), "cities.txt must be sorted");
        // Every name is found by the binary search, and every line reads.
        assert!(cities().all(|(name, rest)| City::parse(rest).is_some() && city(name) == City::parse(rest)));
        assert_eq!(city("zzzzzz"), None);
        assert_eq!(city("aaa"), None);
    }

    #[test]
    fn locates_cities_not_regions() {
        let latitude = |name: &str| locate(name).map(|l| l.latitude);
        assert_eq!(latitude("tokyo"), Some(35.69));
        // Listed with coordinates: cities.txt drops names that are English words.
        assert_eq!(latitude("bath"), Some(51.38));
        assert_eq!(latitude("san fernando del valle de catamarca"), Some(-28.47));
        // A zone's old name keeps the same time as the city's zone.
        assert_eq!(latitude("calcutta"), Some(22.56));
        assert_eq!(latitude("istanbul"), Some(41.01));
        // A zone's own city, from the tz database.
        assert_eq!(latitude("zurich"), Some(47.38));
        // Regions and zone names are no single place; the state of Washington
        // is not the city, which keeps other time.
        assert_eq!(latitude("texas"), None);
        assert_eq!(latitude("pst"), None);
        assert_eq!(latitude("washington state"), None);
        assert_eq!(latitude("washington"), Some(38.9));
        let new_york = zone_location(&TimeZone::get("America/New_York").unwrap()).unwrap();
        assert_eq!((new_york.latitude, new_york.longitude), (40.71, -74.01));
    }

    #[test]
    fn coordinates_are_on_earth() {
        let valid = |(lat, lon): (f64, f64)| (-90.0..=90.0).contains(&lat) && (-180.0..=180.0).contains(&lon);
        for line in ZONE_COORDINATES.lines().filter(|l| !l.starts_with('#')) {
            let id = line.split('\t').next().unwrap();
            assert!(zone_coordinates(id).is_some_and(valid), "{line}");
        }
        for (name, l) in INDEX.iter() {
            assert!(l.coordinates.is_none_or(valid), "{name}");
        }
    }

    #[test]
    fn suggests_close_spellings() {
        assert_eq!(suggest("marseile").as_deref(), Some("Marseille"));
        assert_eq!(suggest("xqzwv"), None);
    }

    #[test]
    fn city_zones_exist() {
        let mut ids: Vec<&str> = cities().filter_map(|(_, rest)| Some(City::parse(rest)?.zone)).collect();
        ids.sort_unstable();
        ids.dedup();
        for id in ids {
            assert!(TimeZone::get(id).is_ok(), "{id}");
        }
    }

    #[test]
    fn all_listed_zones_exist() {
        for (name, l) in INDEX.iter() {
            assert!(listed(&l.zone).is_some(), "{name} = {}", l.zone);
        }
    }
}
